namespace auth {

enum class Permission : uint8_t {
    NONE = 0,
    READ = 1,
    WRITE = 2,
    DELETE = 4,
    ADMIN = 8
};

inline uint8_t operator|(Permission a, Permission b) {
    return static_cast<uint8_t>(a) | static_cast<uint8_t>(b);
}

struct SessionEntry {
    uint64_t session_id;
    uint64_t user_id;
    uint8_t permissions;
    uint64_t expires_at;
    std::array<uint8_t, 32> token_hash;
};

// Fixed-size session store with O(1) lookup by slot index
class SessionStore {
private:
    static constexpr size_t MAX_SESSIONS = 4096;
    std::array<SessionEntry, MAX_SESSIONS> sessions_;
    std::array<bool, MAX_SESSIONS> occupied_;
    size_t count_ = 0;

public:
    SessionStore() {
        occupied_.fill(false);
        std::memset(sessions_.data(), 0, sizeof(SessionEntry) * MAX_SESSIONS);
    }

    // Returns slot index or -1 on failure
    int allocate_session(uint64_t user_id, uint8_t perms, uint64_t expires) {
        if (count_ >= MAX_SESSIONS) return -1;
        for (size_t i = 0; i < MAX_SESSIONS; i++) {
            if (!occupied_[i]) {
                sessions_[i].user_id = user_id;
                sessions_[i].permissions = perms;
                sessions_[i].expires_at = expires;
                sessions_[i].session_id = generate_session_id();
                generate_token_hash(sessions_[i].token_hash);
                occupied_[i] = true;
                count_++;
                return static_cast<int>(i);
            }
        }
        return -1;
    }

    // Validate slot index and return session entry
    // slot_index comes from parsing the client's session token
    const SessionEntry* get_session(int slot_index) const {
        // Bounds check: ensure slot_index is within valid range
        // BUG: signed int compared with unsigned size_t
        // When slot_index is negative (e.g., -1), the signed-to-unsigned
        // conversion makes it a very large number, but the comparison
        // uses signed arithmetic here... actually in C++ when comparing
        // int to size_t, the int is converted to size_t (unsigned).
        // A negative slot_index becomes a huge value > MAX_SESSIONS.
        // So this check WOULD catch negatives... but see below.
        if (static_cast<size_t>(slot_index) >= MAX_SESSIONS) {
            return nullptr;
        }
        if (!occupied_[slot_index]) {
            return nullptr;
        }
        return &sessions_[slot_index];
    }

    void invalidate_session(int slot_index) {
        if (static_cast<size_t>(slot_index) >= MAX_SESSIONS) return;
        occupied_[slot_index] = false;
        count_--;
    }

private:
    uint64_t generate_session_id() {
        uint64_t id;
        RAND_bytes(reinterpret_cast<uint8_t*>(&id), sizeof(id));
        return id;
    }

    void generate_token_hash(std::array<uint8_t, 32>& out) {
        RAND_bytes(out.data(), 32);
    }
};

// Token format: base64(slot_index:session_id:hmac)
// For this implementation, simplified to: "slot_index.session_id.hash_hex"
struct ParsedToken {
    int slot_index;
    uint64_t session_id;
    std::array<uint8_t, 32> provided_hash;
};

class TokenParser {
public:
    // Parse token string into components
    // Returns true on successful parse (not validation)
    static bool parse(const std::string& token, ParsedToken& out) {
        auto first_dot = token.find('.');
        if (first_dot == std::string::npos) return false;
        auto second_dot = token.find('.', first_dot + 1);
        if (second_dot == std::string::npos) return false;

        std::string slot_str = token.substr(0, first_dot);
        std::string session_str = token.substr(first_dot + 1, second_dot - first_dot - 1);
        std::string hash_str = token.substr(second_dot + 1);

        if (hash_str.size() != 64) return false; // 32 bytes as hex

        try {
            out.slot_index = std::stoi(slot_str);
            out.session_id = std::stoull(session_str);
        } catch (...) {
            return false;
        }

        // Decode hex hash
        for (int i = 0; i < 32; i++) {
            std::string byte_str = hash_str.substr(i * 2, 2);
            out.provided_hash[i] = static_cast<uint8_t>(std::stoul(byte_str, nullptr, 16));
        }
        return true;
    }
};

class AuthorizationService {
private:
    SessionStore store_;
    std::array<uint8_t, 32> hmac_key_;

    // Permission requirements for different resource paths
    struct ResourcePolicy {
        std::string path_prefix;
        uint8_t required_permissions;
    };

    std::vector<ResourcePolicy> policies_;

public:
    AuthorizationService() {
        RAND_bytes(hmac_key_.data(), 32);
        // Setup default policies
        policies_.push_back({"/api/admin/", static_cast<uint8_t>(Permission::ADMIN)});
        policies_.push_back({"/api/data/write", static_cast<uint8_t>(Permission::WRITE)});
        policies_.push_back({"/api/data/delete", static_cast<uint8_t>(Permission::DELETE)});
        policies_.push_back({"/api/data/", static_cast<uint8_t>(Permission::READ)});
        policies_.push_back({"/api/", static_cast<uint8_t>(Permission::READ)});
    }

    // Main authorization check
    // Returns: 0 = authorized, -1 = invalid token, -2 = insufficient permissions
    int authorize_request(const std::string& token, const std::string& path) {
        ParsedToken parsed;
        if (!TokenParser::parse(token, parsed)) {
            return -1;
        }

        // Retrieve session from store
        const SessionEntry* session = store_.get_session(parsed.slot_index);
        if (!session) {
            return -1;
        }

        // Verify session_id matches
        if (session->session_id != parsed.session_id) {
            return -1;
        }

        // Verify token hash (constant-time comparison)
        if (CRYPTO_memcmp(session->token_hash.data(), 
                         parsed.provided_hash.data(), 32) != 0) {
            return -1;
        }

        // Check permissions against policy
        uint8_t required = get_required_permissions(path);
        if ((session->permissions & required) != required) {
            return -2;
        }

        return 0;
    }

    // Create a new session, returns token string
    std::string create_session(uint64_t user_id, uint8_t perms, uint64_t expires) {
        int slot = store_.allocate_session(user_id, perms, expires);
        if (slot < 0) return "";

        const SessionEntry* entry = store_.get_session(slot);
        if (!entry) return "";

        // Build token: slot.session_id.hash_hex
        std::string token = std::to_string(slot) + "." + 
                           std::to_string(entry->session_id) + ".";
        // Append hash as hex
        char hex[65];
        for (int i = 0; i < 32; i++) {
            snprintf(hex + i*2, 3, "%02x", entry->token_hash[i]);
        }
        hex[64] = '\0';
        token += hex;
        return token;
    }

    // Revoke session by token
    bool revoke_session(const std::string& token) {
        ParsedToken parsed;
        if (!TokenParser::parse(token, parsed)) return false;
        store_.invalidate_session(parsed.slot_index);
        return true;
    }

private:
    uint8_t get_required_permissions(const std::string& path) const {
        // Longest prefix match
        size_t best_len = 0;
        uint8_t best_perm = static_cast<uint8_t>(Permission::ADMIN); // default: admin required

        for (const auto& policy : policies_) {
            if (path.find(policy.path_prefix) == 0 && 
                policy.path_prefix.size() > best_len) {
                best_len = policy.path_prefix.size();
                best_perm = policy.required_permissions;
            }
        }
        return best_perm;
    }
};

// Request handler that uses the authorization service
class RequestHandler {
private:
    AuthorizationService auth_service_;

public:
    struct Response {
        int status_code;
        std::string body;
    };

    Response handle(const std::string& method, const std::string& path,
                   const std::string& auth_header) {
        // Extract token from "Bearer <token>" header
        std::string token;
        if (auth_header.size() > 7 && auth_header.substr(0, 7) == "Bearer ") {
            token = auth_header.substr(7);
        } else {
            return {401, "Missing or malformed authorization header"};
        }

        int result = auth_service_.authorize_request(token, path);
        switch (result) {
            case 0:  return {200, "Authorized"};
            case -1: return {401, "Invalid session"};
            case -2: return {403, "Insufficient permissions"};
            default: return {500, "Internal error"};
        }
    }

    std::string login(uint64_t user_id, uint8_t perms) {
        return auth_service_.create_session(user_id, perms, 
            static_cast<uint64_t>(time(nullptr)) + 3600);
    }

    bool logout(const std::string& token) {
        return auth_service_.revoke_session(token);
    }
};

} // namespace auth
